/// Measured group times, generated by `tools/bazel/libtest_shards.py --groups`.
pub const WEIGHTS: &str = concat!(
    env!("CARGO_MANIFEST_DIR"),
    "/../../tools/bazel/libtest-shards.json"
);
const WORKERS: &str = "tl3-controller/workers";

macro_rules! worker_groups {
    ($($group:ident: $markers:expr),* $(,)?) => {
        #[derive(Clone, Copy, Debug, Eq, Hash, PartialEq)]
        pub enum WorkerGroup { $($group),* }

        pub const WORKER_GROUPS: &[WorkerGroup] = &[$(WorkerGroup::$group),*];

        impl WorkerGroup {
            pub const fn markers(self) -> usize {
                match self { $(Self::$group => $markers),* }
            }

            pub const fn name(self) -> &'static str {
                match self { $(Self::$group => stringify!($group)),* }
            }
        }
    };
}

