/// Milliseconds per group: the measured time, or the median measured group
/// for a group without one, such as a new group.
pub fn weights_ms(
    measured: &serde_json::Map<String, serde_json::Value>,
    groups: &[&str],
) -> Vec<usize> {
    let ms = |seconds: &serde_json::Value| {
        let seconds = seconds.as_f64().expect("group seconds are numbers");
        (seconds * 1000.0).round() as usize
    };
    let mut known: Vec<_> = measured.values().map(ms).collect();
    known.sort_unstable();
    let median = known.get(known.len() / 2).copied().unwrap_or(1000);
    groups
        .iter()
        .map(|group| measured.get(*group).map_or(median, ms))
        .collect()
}

/// This binary's measured group weights from [`WEIGHTS`].
pub fn measured(binary: &str) -> serde_json::Map<String, serde_json::Value> {
    let text = fs::read_to_string(WEIGHTS).expect("read tools/bazel/libtest-shards.json");
    let mut all: serde_json::Value = serde_json::from_str(&text).expect("shard weights are JSON");
    match all.get_mut(binary).map(serde_json::Value::take) {
        Some(serde_json::Value::Object(groups)) => groups,
        _ => serde_json::Map::new(),
    }
}

/// Assign each declared scenario group to exactly one Bazel shard.
/// Groups keep their original fixture lifetime and scenario timing markers.
pub struct Shard<G = WorkerGroup> {
    index: usize,
    groups: Vec<G>,
    markers: HashMap<G, usize>,
    owners: HashMap<G, usize>,
    planned: HashSet<G>,
    selected: usize,
}

impl Shard {
    pub fn from_env() -> Self {
        let parse = |name: &str, default| {
            env::var(name).map_or(default, |value| value.parse().expect("invalid Bazel shard"))
        };
        let index = parse("TEST_SHARD_INDEX", 0);
        let total = parse("TEST_TOTAL_SHARDS", 1);
        Self::new(index, total)
    }

    pub fn new(index: usize, total: usize) -> Self {
        let names: Vec<_> = WORKER_GROUPS.iter().map(|group| group.name()).collect();
        let weights = weights_ms(&measured(WORKERS), &names);
        Self::with_groups(
            index,
            total,
            &WORKER_GROUPS
                .iter()
                .zip(weights)
                .map(|(group, weight)| (*group, group.markers(), weight))
                .collect::<Vec<_>>(),
        )
    }

    pub fn unsharded() -> Self {
        Self::new(0, 1)
    }
}

impl<G: Copy + Debug + Eq + Hash> Shard<G> {
    pub fn from_groups(groups: &[(G, usize, usize)]) -> Self {
        let parse = |name: &str, default| {
            env::var(name).map_or(default, |value| value.parse().expect("invalid Bazel shard"))
        };
        Self::with_groups(
            parse("TEST_SHARD_INDEX", 0),
            parse("TEST_TOTAL_SHARDS", 1),
            groups,
        )
    }

    pub fn with_groups(index: usize, total: usize, groups: &[(G, usize, usize)]) -> Self {
        assert!(
            total > 0 && index < total,
            "invalid Bazel shard index/count"
        );
        let declared: Vec<_> = groups.iter().map(|(group, _, _)| *group).collect();
        let markers: HashMap<_, _> = groups
            .iter()
            .map(|(group, markers, _)| (*group, *markers))
            .collect();
        assert_eq!(
            markers.len(),
            groups.len(),
            "duplicate scenario group declaration"
        );
        let mut groups = groups.to_vec();
        groups.sort_by_key(|(_, _, seconds)| Reverse(*seconds));
        let mut loads = vec![0; total];
        let mut owners = HashMap::new();
        for (group, _, seconds) in groups {
            let owner = loads
                .iter()
                .enumerate()
                .min_by_key(|(_, load)| *load)
                .unwrap()
                .0;
            loads[owner] += seconds;
            owners.insert(group, owner);
        }
        Self {
            index,
            groups: declared,
            markers,
            owners,
            planned: HashSet::new(),
            selected: 0,
        }
    }

    pub fn run(&mut self, group: G, scenario: impl FnOnce()) {
        assert!(
            self.planned.insert(group),
            "duplicate scenario group: {group:?}"
        );
        let markers = self.markers[&group];
        let owner = self.owners[&group];
        if owner == self.index {
            let started = Instant::now();
            scenario();
            // libtest_shards.py --groups turns these lines into the shard weights.
            println!(
                "scenario group {group:?}: {:.3}s",
                started.elapsed().as_secs_f64()
            );
            self.selected += markers;
        }
    }

    pub fn finish(self, label: &str) {
        for group in &self.groups {
            assert!(
                self.planned.contains(group),
                "missing scenario group: {group:?}"
            );
        }
        assert!(self.selected > 0, "empty scenario shard");
        println!("{} {label} scenarios passed; no skips", self.selected);
    }
}
